--
-- A9. Action bar for a new Death Knight of each race -- 30 rows.
--
-- Button 1 holds the custom rank (90000), so the acceptance test -- hover it
-- and read "10-12 Frost damage" -- needs no setup. The stock rows handed out
-- 45477/45462/45902/47541/49576, all level 55 abilities the character will not know.
-- 6603 is Attack. The third button is the race's own racial, on the slot and
-- with the spell Blizzard shipped for that race's Death Knight; the slot is not uniform:
--
--    1 Human      button 11  59752  Every Man for Himself
--    2 Orc        button 10  20572  Blood Fury
--    3 Dwarf      button 10   2481  Find Treasure
--    4 Night Elf  button 10  58984  Shadowmeld
--    5 Undead     button 10  20577  Cannibalize
--    6 Tauren     button 10  20549  War Stomp
--    7 Gnome      button 10  20589  Escape Artist
--    8 Troll      button 10  26297  Berserking
--   10 Blood Elf  button  6  50613  Arcane Torrent
--   11 Draenei    button 10  59545  Gift of the Naaru

DELETE FROM `playercreateinfo_action` WHERE `class` = 6 AND `race` IN (1, 2, 3, 4, 5, 6, 7, 8, 10, 11);
INSERT INTO `playercreateinfo_action` (`race`, `class`, `button`, `action`, `type`) VALUES
  (1, 6, 0, 6603, 0),
  (1, 6, 1, 90000, 0),
  (1, 6, 11, 59752, 0),
  (2, 6, 0, 6603, 0),
  (2, 6, 1, 90000, 0),
